// Cooling-silence index — record JAH-GPC-AIOCOOLER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"tdp_rating_w": 250, "noise_db": 32};
var value = (m.tdp_rating_w/m.noise_db*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-AIOCOOLER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-AIOCOOLER-000001|' + value.toFixed(2) + ' cooling-silence index');

